import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import openapiTS, { astToString } from "openapi-typescript";

const root = resolve(import.meta.dirname, "..");
const generated = resolve(root, "src", "schema.ts");
const source = JSON.parse(readFileSync(resolve(root, "openapi.json"), "utf8"));
const banner = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;
const expected = banner + astToString(await openapiTS(source));

if (readFileSync(generated, "utf8") !== expected) {
  throw new Error(
    "Generated TypeScript contract drifted; run pnpm contracts:generate",
  );
}
